import{_ as p,a0 as o,w as d,s as r,ao as l,I as e,x as s,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"通過玩命令列遊戲來測試你的 BASH 技能 | LCTT x X-CMD","titleTemplate":false,"description":"通過玩命令列遊戲來測試你的 BASH 技能 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過玩命令列遊戲來測試你的 BASH 技能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過玩命令列遊戲來測試你的 BASH 技能 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180308 Test Your BASH Skills By Playing Command Line Games","title":"通過玩命令列遊戲來測試你的 BASH 技能","tag":"201803","desc":""},"relativePath":"201803/20180308 Test Your BASH Skills By Playing Command Line Games.md","filePath":"[post].md"}'),m={name:"201803/20180308 Test Your BASH Skills By Playing Command Line Games.md"};function h(u,t,g,b,k,y){const i=o("Link");return d(),r("div",null,[t[26]||(t[26]=l('<h1 id="通過玩命令列遊戲來測試你的-bash-技能" tabindex="-1">通過玩命令列遊戲來測試你的 BASH 技能 <a class="header-anchor" href="#通過玩命令列遊戲來測試你的-bash-技能" aria-label="Permalink to “通過玩命令列遊戲來測試你的 BASH 技能”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Test-your-bash-skills-1-720x340.png" alt=""></p><p>如果我們經常在實際場景中使用 Linux 命令，我們就會更有效的學習和記憶它們。除非你經常使用 Linux 命令，否則你可能會在一段時間內忘記它們。無論你是新手還是老手，總會有一些趣味的方法來測試你的 BASH 技能。在本教程中，我將解釋如何通過玩命令列遊戲來測試你的 BASH 技能。其實從技術上講，這些並不是像 Super TuxKart、極品飛車或 CS 等真正的遊戲。這些只是 Linux 命令培訓課程的遊戲化版本。你將需要根據遊戲本身的某些指示來完成一個任務。</p><p>現在，我們來看看幾款能幫助你實時學習和練習 Linux 命令的遊戲。這些遊戲不是消磨時間或者令人驚詫的，這些遊戲將幫助你獲得終端命令的真實體驗。請繼續閲讀：</p><h3 id="使用-wargames-來測試-bash-技能" tabindex="-1">使用 “Wargames” 來測試 BASH 技能 <a class="header-anchor" href="#使用-wargames-來測試-bash-技能" aria-label="Permalink to “使用 “Wargames” 來測試 BASH 技能”">​</a></h3><p>這是一個在線遊戲，所以你必須聯網。這些遊戲可以幫助你以充滿樂趣的遊戲形式學習和練習 Linux 命令。Wargames 是一個 shell 遊戲的集合，每款遊戲有很多關卡。只有通過解決先前的關卡才能訪問下一個關卡。不要擔心！每個遊戲都提供了有關如何進入下一關的清晰簡潔説明。</p>',6)),e("p",null,[t[1]||(t[1]=s("要玩 Wargames，請點擊以下鏈接：",-1)),n(i,{href:"http://overthewire.org/wargames/"},{default:a(()=>[...t[0]||(t[0]=[s("Wargames",-1)])]),_:1}),t[2]||(t[2]=s(" 。",-1))]),t[27]||(t[27]=l('<p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Wargames-1.png" alt=""></p><p>如你所見，左邊列出了許多 shell 遊戲。每個 shell 遊戲都有自己的 SSH 端口。所以，你必須通過本地系統配置 SSH 連接到遊戲，你可以在 Wargames 網站的左上角找到關於如何使用 SSH 連接到每個遊戲的信息。</p><p>例如，讓我們來玩 Bandit 遊戲吧。為此，單擊 Wargames 主頁上的 Bandit 鏈接。在左上角，你會看到 Bandit 遊戲的 SSH 信息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Bandit-game.png" alt=""></p><p>正如你在上面的屏幕截圖中看到的，有很多關卡。要進入每個關卡，請單機左側列中的相應鏈接。此外，右側還有適合初學者的説明。如果你對如何玩此遊戲有任何疑問，請閲讀它們。</p><p>現在，讓我們點擊它進入關卡 0。在下一個屏幕中，你將獲得該關卡的 SSH 信息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Bandit-level-0.png" alt=""></p><p>正如你在上面的屏幕截圖中看到的，你需要配置 SSH 端口 2220 連接 <code>bandit.labs.overthewire.org</code>，用户名是 <code>bandit0</code>，密碼是 <code>bandit0</code>。</p><p>讓我們連接到 Bandit 遊戲關卡 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh bandit0@bandit.labs.overthewire.org -p 2220</span></span></code></pre></div><p>輸入密碼 <code>bandit0</code>。</p><p>示例輸出將是：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Bandit-level-0-ssh-1.png" alt=""></p><p>登錄後，輸入 <code>ls</code> 命令查看內容或者進入關卡 1 頁面，瞭解如何通過關卡 1 等等。建議的命令列表已在每個關卡提供。所以，你可以選擇和使用任何合適的命令來解決每個關卡。</p><p>我必須承認，Wargames 是令人上癮的，並且解決每個關卡是非常有趣的。 儘管有些關卡確實很具挑戰性，你可能需要谷歌才能知道如何解決問題。 試一試，你會很喜歡它。</p><h3 id="使用-terminus-來測試-bash-技能" tabindex="-1">使用 “Terminus” 來測試 BASH 技能 <a class="header-anchor" href="#使用-terminus-來測試-bash-技能" aria-label="Permalink to “使用 “Terminus” 來測試 BASH 技能”">​</a></h3>',16)),e("p",null,[t[4]||(t[4]=s("這是另一個基於瀏覽器的在線 CLI 遊戲，可用於改進或測試你的 Linux 命令技能。要玩這個遊戲，請打開你的 web 瀏覽器並導航到以下 URL：",-1)),n(i,{href:"http://web.mit.edu/mprat/Public/web/Terminus/Web/main.html"},{default:a(()=>[...t[3]||(t[3]=[s("Play Terminus Game",-1)])]),_:1})]),t[28]||(t[28]=l('<p>一旦你進入遊戲，你會看到有關如何玩遊戲的説明。與 Wargames 不同，你不需要連接到它們的遊戲服務器來玩遊戲。Terminus 有一個內置的 CLI，你可以在其中找到有關如何使用它的説明。</p><p>你可以使用命令 <code>ls</code> 查看周圍的環境，使用命令 <code>cd 位置</code> 移動到新的位置，返回使用命令 <code>cd ..</code>，與這個世界進行交互使用命令 <code>less 項目</code> 等等。要知道你當前的位置，只需輸入 <code>pwd</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Terminus.png" alt=""></p><h3 id="使用-clmystery-來測試-bash-技能" tabindex="-1">使用 “clmystery” 來測試 BASH 技能 <a class="header-anchor" href="#使用-clmystery-來測試-bash-技能" aria-label="Permalink to “使用 “clmystery” 來測試 BASH 技能”">​</a></h3><p>與上述遊戲不同，你可以在本地玩這款遊戲。你不需要連接任何遠程系統，這是完全離線的遊戲。</p><p>相信我，這傢伙是一個有趣的遊戲。按照給定的説明，你將扮演一個偵探角色來解決一個神秘案件。</p><p>首先，克隆倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/veltman/clmystery.git</span></span></code></pre></div>',8)),e("p",null,[t[6]||(t[6]=s("或者，從 ",-1)),n(i,{href:"https://github.com/veltman/clmystery/archive/master.zip"},{default:a(()=>[...t[5]||(t[5]=[s("這裏",-1)])]),_:1}),t[7]||(t[7]=s(" 將其作為 zip 文件下載。解壓縮並切換到下載文件的地方。最後，通過閲讀 ",-1)),t[8]||(t[8]=e("code",null,"instructions",-1)),t[9]||(t[9]=s(" 文件來開啓寶箱。",-1))]),t[29]||(t[29]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[sk@sk]: clmystery-master&gt;$ ls</span></span>
<span class="line"><span>cheatsheet.md cheatsheet.pdf encoded hint1 hint2 hint3 hint4 hint5 hint6 hint7 hint8 instructions LICENSE.md mystery README.md solution</span></span></code></pre></div><p>這裏是玩這個遊戲的説明：</p><p>終端城發生了一起謀殺案，TCPD 需要你的幫助。你需要幫助它們弄清楚是誰犯罪了。</p><p>為了查明是誰幹的，你需要到 <code>mystery</code> 子目錄並從那裏開始工作。你可能需要查看犯罪現場的所有線索（ <code>crimescene</code> 文件）。現場的警官相當謹慎，所以他們在警官報告中寫下了一切。幸運的是，警官以全部大寫的 “CLUE” 一詞把真正的線索標記了出來。</p><p>如果裏遇到任何問題，請打開其中一個提示文件，例如 “hint1”，“hint2” 等。你可以使用下面的 <code>cat</code> 命令打開提示文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat hint1</span></span>
<span class="line"><span>$ cat hint2</span></span></code></pre></div><p>要檢查你的答案或找出解決方案，請在 <code>clmystery</code> 目錄中打開文件 <code>solution</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat solution</span></span></code></pre></div><p>要了解如何使用命令列，請參閲 <code>cheatsheet.md</code> 或 <code>cheatsheet.pdf</code> （在命令列中，你可以輸入 ‘nano cheatsheet.md’）。請勿使用文本編輯器查看除 <code>instructions</code>、<code>cheatsheet</code> 和 <code>hint</code> 以外的任何文件。</p>`,9)),e("p",null,[t[11]||(t[11]=s("有關更多詳細信息，請參閲 ",-1)),n(i,{href:"https://github.com/veltman/clmystery"},{default:a(()=>[...t[10]||(t[10]=[s("clmystery GitHub",-1)])]),_:1}),t[12]||(t[12]=s(" 頁面。",-1))]),t[30]||(t[30]=e("p",null,"推薦閲讀：",-1)),t[31]||(t[31]=e("p",null,"而這就是我現在所知道的。如果將來遇到任何問題，我會繼續添加更多遊戲。將此鏈接加入書籤並不時訪問。如果你知道其他類似的遊戲，請在下面的評論部分告訴我，我將測試和更新本指南。",-1)),t[32]||(t[32]=e("p",null,"還有更多好東西，敬請關注！",-1)),t[33]||(t[33]=e("p",null,"乾杯！",-1)),t[34]||(t[34]=e("hr",null,null,-1)),e("p",null,[t[14]||(t[14]=s("via: ",-1)),n(i,{href:"https://www.ostechnix.com/test-your-bash-skills-by-playing-command-line-games/"},{default:a(()=>[...t[13]||(t[13]=[s("https://www.ostechnix.com/test-your-bash-skills-by-playing-command-line-games/",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=s("作者：",-1)),n(i,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...t[15]||(t[15]=[s("SK",-1)])]),_:1}),t[19]||(t[19]=s(" 譯者：",-1)),n(i,{href:"https://github.com/MjSeven"},{default:a(()=>[...t[16]||(t[16]=[s("MjSeven",-1)])]),_:1}),t[20]||(t[20]=s(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[17]||(t[17]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[23]||(t[23]=s("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[s("LCTT",-1)])]),_:1}),t[24]||(t[24]=s(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[s("Linux中國",-1)])]),_:1}),t[25]||(t[25]=s(" 榮譽推出",-1))])])}const c=p(m,[["render",h]]);export{f as __pageData,c as default};
